package org.ruoyi.ipd.agent.catalog;

import org.ruoyi.service.coding.harness.tool.ToolCapability;
import org.ruoyi.service.coding.harness.tool.ToolDescriptor;

import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * 项目智能体工具目录（W1 仅一个只读工具）。
 *
 * <p>工具安全元数据以既有自研 {@link ToolDescriptor} 声明，由 {@code ToolPolicyEngine}
 * 作为唯一裁决源（红线 D1：不另造白名单语义）。清单登记而本目录无实现的工具一律不可用。
 */
public final class ProjectAgentToolCatalog {

    /** 项目资料检索（只读）工具 ID。 */
    public static final String PROJECT_KNOWLEDGE_SEARCH = "project_knowledge_search";

    /** 工具可用性投影。 */
    public record ToolStatus(String id, String name, boolean readOnly, boolean available, String reason) { }

    private static final Map<String, ToolDescriptor> DESCRIPTORS = descriptors();

    /**
     * 本地资料检索，加上清单里的服务标识。名称不参与能否调用。
     *
     * @return 工具安全描述
     */
    private static Map<String, ToolDescriptor> descriptors() {
        Map<String, ToolDescriptor> map = new HashMap<>();
        map.put(PROJECT_KNOWLEDGE_SEARCH, descriptor(PROJECT_KNOWLEDGE_SEARCH,
            "只读检索本项目已审核文档片段；项目范围由运行绑定，不接受模型传入"));
        for (ProductLineMcpCatalog.Endpoint endpoint : ProductLineMcpCatalog.all()) {
            map.put(endpoint.serviceId(), descriptor(endpoint.serviceId(),
                "只读查询产线「" + endpoint.lineName() + "」；服务标识 " + endpoint.serviceId()));
        }
        return Map.copyOf(map);
    }

    private static ToolDescriptor descriptor(String toolId, String summary) {
        return new ToolDescriptor(toolId, EnumSet.of(ToolCapability.READ, ToolCapability.SEARCH),
            true, 30_000L, 4_096L, 16_384L, false, summary);
    }

    private final CapabilityManifest manifest;

    /**
     * @param manifest 内置清单
     */
    public ProjectAgentToolCatalog(CapabilityManifest manifest) {
        this.manifest = manifest;
    }

    /**
     * 清单工具的可用性。
     *
     * @return 状态列表
     */
    public List<ToolStatus> statuses() {
        return manifest.tools().stream().map(t -> status(t.id())).toList();
    }

    /**
     * 单个工具可用性。
     *
     * @param toolId 工具 ID
     * @return 状态
     */
    public ToolStatus status(String toolId) {
        CapabilityManifest.ToolEntry entry = manifest.tool(toolId).orElse(null);
        if (entry == null) {
            return new ToolStatus(toolId, null, false, false, "工具未在内置清单登记");
        }
        ToolDescriptor descriptor = DESCRIPTORS.get(toolId);
        if (descriptor == null) {
            return new ToolStatus(toolId, entry.name(), entry.readOnly(), false, "工具实现未交付");
        }
        boolean readOnly = !descriptor.hasCapability(ToolCapability.WRITE)
            && !descriptor.hasCapability(ToolCapability.DESTRUCTIVE)
            && !descriptor.hasCapability(ToolCapability.EXECUTE)
            && !descriptor.hasCapability(ToolCapability.NETWORK);
        if (!readOnly) {
            return new ToolStatus(toolId, entry.name(), false, false, "W1 仅开放只读工具");
        }
        return new ToolStatus(toolId, entry.name(), true, true, null);
    }

    /**
     * 工具安全描述（裁决源输入）。
     *
     * @param toolId 工具 ID
     * @return 描述；未实现为 null
     */
    public static ToolDescriptor descriptor(String toolId) {
        return DESCRIPTORS.get(toolId);
    }
}

package org.ruoyi.ipd.agent.service;

import org.ruoyi.ipd.agent.ProjectAgentConstants;
import org.ruoyi.ipd.agent.catalog.CapabilityManifest;
import org.ruoyi.ipd.agent.catalog.CapabilityManifest.PackEntry;
import org.ruoyi.ipd.agent.catalog.ProjectAgentModelCatalog;
import org.ruoyi.ipd.agent.catalog.ProjectAgentSkillCatalog;
import org.ruoyi.ipd.agent.catalog.ProjectAgentToolCatalog;
import org.ruoyi.ipd.agent.vo.ProjectAgentViews;
import org.ruoyi.ipd.common.ApiV1ErrorCode;
import org.ruoyi.ipd.common.IpdBusinessException;
import org.ruoyi.ipd.security.IpdActor;
import org.ruoyi.ipd.service.IpdCopilotAccess;

import java.util.List;
import java.util.Objects;

/**
 * 项目智能体能力目录（合同 #1）：服务端按 Person/项目返回可运行选项与不可用原因。
 *
 * <p>开关关闭时仍返回完整目录，但所有能力包 available=false、unavailableReason 明确为
 * {@link ProjectAgentConstants#REASON_DISABLED}，不静默降级到副驾；Skill/工具/模型各自的
 * 可用性照常如实返回（便于部署前核对安装内容）。本接口不读写 ipd_agent_* 表。
 */
public class ProjectAgentCapabilityService {

    private final boolean enabled;
    private final IpdCopilotAccess access;
    private final CapabilityManifest manifest;
    private final ProjectAgentSkillCatalog skillCatalog;
    private final ProjectAgentToolCatalog toolCatalog;
    private final ProjectAgentModelCatalog modelCatalog;

    /**
     * @param enabled 开关
     * @param access 项目访问守卫
     * @param manifest 内置清单
     * @param skillCatalog Skill 目录
     * @param toolCatalog 工具目录
     * @param modelCatalog 模型目录
     */
    public ProjectAgentCapabilityService(boolean enabled, IpdCopilotAccess access, CapabilityManifest manifest,
                                         ProjectAgentSkillCatalog skillCatalog, ProjectAgentToolCatalog toolCatalog,
                                         ProjectAgentModelCatalog modelCatalog) {
        this.enabled = enabled;
        this.access = Objects.requireNonNull(access, "access");
        this.manifest = Objects.requireNonNull(manifest, "manifest");
        this.skillCatalog = Objects.requireNonNull(skillCatalog, "skillCatalog");
        this.toolCatalog = Objects.requireNonNull(toolCatalog, "toolCatalog");
        this.modelCatalog = Objects.requireNonNull(modelCatalog, "modelCatalog");
    }

    /**
     * 查询能力目录（先做项目可见性校验）。
     *
     * @param actor 会话身份
     * @param projectId 项目 ID
     * @return 能力包 + 模型
     */
    public ProjectAgentViews.Capabilities capabilities(IpdActor actor, Long projectId) {
        if (projectId == null) {
            throw new IpdBusinessException(ApiV1ErrorCode.PARAM_INVALID, "projectId 必填");
        }
        access.requireVisible(actor, projectId);
        List<ProjectAgentViews.Model> models = modelCatalog.statuses().stream()
            .map(m -> new ProjectAgentViews.Model(m.id(), m.name(), m.available(), m.reason()))
            .toList();
        boolean anyModel = models.stream().anyMatch(ProjectAgentViews.Model::available);
        List<ProjectAgentViews.Pack> packs = manifest.packs().stream().map(p -> pack(p, anyModel)).toList();
        return new ProjectAgentViews.Capabilities(packs, models);
    }

    private ProjectAgentViews.Pack pack(PackEntry entry, boolean anyModel) {
        List<ProjectAgentViews.Skill> skills = entry.skills().stream().map(skillCatalog::status)
            .map(s -> new ProjectAgentViews.Skill(s.name(), s.version(), s.sha256(), s.available(), s.reason()))
            .toList();
        List<ProjectAgentViews.Tool> tools = entry.tools().stream().map(toolCatalog::status)
            .map(t -> new ProjectAgentViews.Tool(t.id(), t.name(), t.readOnly(), t.available(), t.reason()))
            .toList();
        String reason = unavailableReason(skills, tools, anyModel);
        return new ProjectAgentViews.Pack(entry.code(), entry.version(), entry.name(), entry.description(),
            entry.stages() == null ? List.of() : entry.stages(),
            entry.actionCodes() == null ? List.of() : entry.actionCodes(),
            reason == null, reason, skills, tools);
    }

    private String unavailableReason(List<ProjectAgentViews.Skill> skills, List<ProjectAgentViews.Tool> tools,
                                     boolean anyModel) {
        if (!enabled) {
            return ProjectAgentConstants.REASON_DISABLED;
        }
        for (ProjectAgentViews.Skill skill : skills) {
            if (!skill.available()) {
                return "必需 Skill 不可用：" + skill.name() + "（" + skill.reason() + "）";
            }
        }
        for (ProjectAgentViews.Tool tool : tools) {
            if (!tool.available()) {
                return "必需工具不可用：" + tool.id() + "（" + tool.reason() + "）";
            }
        }
        if (!anyModel) {
            return "无可用模型配置";
        }
        return null;
    }
}
